import { Buffer } from 'node:buffer';
import { createServer } from 'dhcp';

const asHex = (value) => value ? Buffer.from(value).toString('hex') : undefined;
const server = createServer({
    range: ['192.168.3.10', '192.168.3.99'],
    server: '192.168.3.1',
    relayBindings: [{
        address: '192.168.3.20',
        giaddr: '192.168.3.1',
        circuitId: { hex: '000102' },
    }],
    hostname(packet) {

        const circuitId = asHex(packet?.relayAgentInformation?.circuitId);

        return circuitId === '000102' ? 'access-a.example' : 'access-default.example';
    },
    forceOptions: ['hostname'],
});

server.on('message', (packet) => {

    if (!packet.relayAgentInformation) {
        return;
    }
    console.log({
        relay: packet.giaddr,
        circuitId: asHex(packet.relayAgentInformation.circuitId),
        remoteId: asHex(packet.relayAgentInformation.remoteId),
    });
});

server.listen();
